referenceSolutions.javascript:
export function slidingWindowMaximum(values          , k        )           {
const q         =[],out         =[];let head=0;for(let i=0;i<values.length;i++){while(q.length>head&&q[head]<=i-k)head++;while(q.length>head&&values[q[q.length-1]]<=values[i])q.pop();q.push(i);if(i>=k-1)out.push(values[q[head]]);}return out;
}

